<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
final class Commit015DependencyTest extends TestCase
{
 public function testQuillIsExactlyPinnedAndBuiltLocally():void{$root=dirname(__DIR__,2);$package=json_decode((string)file_get_contents($root.'/package.json'),true,512,JSON_THROW_ON_ERROR);self::assertTrue($package['private']);self::assertSame('2.0.3',$package['devDependencies']['quill']);self::assertSame('node scripts/copy-quill-assets.mjs',$package['scripts']['build:vendor']);self::assertFileExists($root.'/package-lock.json');foreach(['quill.js','quill.snow.css','LICENSE'] as $file)self::assertFileExists($root.'/public/assets/vendor/quill/2.0.3/'.$file);$script=(string)file_get_contents($root.'/scripts/copy-quill-assets.mjs');foreach(['http://','https://','fetch(','curl'] as $remote)self::assertStringNotContainsString($remote,$script);foreach(['vite','webpack','rollup','parcel','react','vue'] as $forbidden)self::assertArrayNotHasKey($forbidden,$package['devDependencies']);}
 public function testOfficialAwsSdkV3IsLockedAndNoCredentialIsCommitted():void{$root=dirname(__DIR__,2);$composer=json_decode((string)file_get_contents($root.'/composer.json'),true,512,JSON_THROW_ON_ERROR);self::assertArrayHasKey('aws/aws-sdk-php',$composer['require']);$lock=json_decode((string)file_get_contents($root.'/composer.lock'),true,512,JSON_THROW_ON_ERROR);$aws=array_values(array_filter($lock['packages'],static fn(array $p):bool=>$p['name']==='aws/aws-sdk-php'));self::assertCount(1,$aws);self::assertMatchesRegularExpression('/^v?3\./',$aws[0]['version']);$adapter=(string)file_get_contents($root.'/app/Storage/WasabiStorageAdapter.php');self::assertStringContainsString('implements StorageAdapterInterface',$adapter);self::assertStringContainsString('ObjectUploader',$adapter);self::assertStringNotContainsString('CURLOPT_',$adapter);}
}
